 $makeUser=function(string $key,string $shift='Day',string $role='container_wingvan_dispatcher')use($p){$id=insert($p,'users',['username'=>'guard_'.$key,'email'=>'guard_'.$key.'@example.test','full_name'=>'Guard '.$key,'password_hash'=>'fixture','role'=>$role,'shift'=>$shift]);return ['id'=>$id,'role'=>$role,'shift'=>$shift];};
 $makeTrip=function(string $ref,array $owner,string $status='Awaiting Resources')use($p,$ops,$client){$id=insert($p,'trips',['trip_ref'=>$ref,'intake_source'=>'Operations Head','created_by'=>$ops['id'],'client_id'=>$client,'truck_type'=>'Container','dispatcher_role'=>$owner['role'],'dispatcher_shift'=>$owner['shift'],'pickup_point'=>'Guard origin','delivery_point'=>'Guard destination','scheduled_at'=>date('Y-m-d H:i:s',time()+3600),'status'=>$status]);Trips::action($ops,'turnover_assign_initial',['trip_id'=>$id,'dispatcher_id'=>$owner['id']]);return $id;};
 $edit=function(array $who,string $role,string $shift)use($p){$u=one($p,'SELECT full_name,email FROM users WHERE id=?',[$who['id']]);return ['id'=>$who['id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$role,'shift'=>$shift];};
 $blocked=function(callable $fn,string $label,string $reference=''){try{$fn();turn_ok(false,$label);}catch(BusinessRuleException $e){turn_ok($e->httpStatus===409&&str_contains($e->getMessage(),'Account change blocked')&&($reference===''||str_contains($e->getMessage(),$reference)),$label);}};
