 $blocked(fn()=>Admin::action($admin,'user_save',$edit($out,$out['role'],'Night')),'Outstanding ownership blocks Dispatcher shift change');
 turn_ok(one($p,'SELECT * FROM users WHERE id=?',[$out['id']])===$before&&(int)$p->query('SELECT COUNT(*) FROM audit_events')->fetchColumn()===$auditBefore,'Blocked changes preserve account and existing audit records');
 Admin::action($admin,'user_save',$edit($out,$out['role'],$out['shift']));turn_ok(true,'Ordinary profile edits remain allowed while responsible');
 $preview=Trips::action($out,'turnover_preview',[]);$h=Trips::action($out,'turnover_endorse',['incoming_id'=>$in['id'],'trip_ids'=>array_column($preview['rows'],'id'),'fingerprint'=>$preview['fingerprint'],'request_key'=>turn_key()])['turnover_id'];
 foreach([$out,$in] as $participant){$blocked(fn()=>Admin::action($admin,'user_toggle',['user_id'=>$participant['id'],'active'=>0]),'Pending participant cannot deactivate account #'.$participant['id'],'#'.$h);$blocked(fn()=>Admin::action($admin,'user_save',$edit($participant,'audit','Day')),'Pending participant cannot change role #'.$participant['id']);$blocked(fn()=>Admin::action($admin,'user_save',$edit($participant,$participant['role'],$participant['shift']==='Day'?'Night':'Day')),'Pending participant cannot change shift #'.$participant['id']);}
 $original=one($p,'SELECT dispatcher_role,dispatcher_shift,dispatcher_id FROM trips WHERE id=?',[$trip]);
 Trips::action($in,'turnover_accept',['turnover_id'=>$h]);turn_ok((int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$trip])['current_dispatcher_id']===$in['id'],'Normal Endorse then Accept remains functional with safeguards');
 Admin::action($admin,'user_toggle',['user_id'=>$out['id'],'active'=>0]);turn_ok((int)one($p,'SELECT active FROM users WHERE id=?',[$out['id']])['active']===0,'Accepted history and original ownership do not block outgoing deactivation');
 $blocked(fn()=>Admin::action($admin,'user_toggle',['user_id'=>$in['id'],'active'=>0]),'Incoming owner remains protected after acceptance');
 turn_ok(one($p,'SELECT dispatcher_role,dispatcher_shift,dispatcher_id FROM trips WHERE id=?',[$trip])===$original,'Safeguards preserve original trip actor/planning fields');
 $historic=$makeUser('historic');$closed=$makeTrip('GUARD-HISTORY',$historic,'Completed');Admin::action($admin,'user_save',$edit($historic,'audit','Day'));Admin::action($admin,'user_toggle',['user_id'=>$historic['id'],'active'=>0]);turn_ok((int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$closed])['current_dispatcher_id']===$historic['id'],'Fully completed ownership allows role change/deactivation without rewriting history');
 $idle=$makeUser('idle','Day','car_carrier_dispatcher');Admin::action($admin,'user_toggle',['user_id'=>$idle['id'],'active'=>0]);Admin::action($admin,'user_toggle',['user_id'=>$idle['id'],'active'=>1]);Admin::action($admin,'user_save',$edit($idle,$idle['role'],'Day'));turn_ok((int)one($p,'SELECT active FROM users WHERE id=?',[$idle['id']])['active']===1,'Idle Dispatcher deactivation, reactivation and profile editing remain functional');
 Admin::action($admin,'user_save',$edit($idle,'billing','Day'));Admin::action($admin,'user_save',$edit($idle,$idle['role'],'Day'));turn_ok(one($p,'SELECT role FROM users WHERE id=?',[$idle['id']])['role']===$idle['role'],'Idle account role changes remain functional when the destination slot is vacant');
 Admin::action($admin,'user_toggle',['user_id'=>$idle['id'],'active'=>0]);Admin::action($admin,'user_save',$edit($idle,$idle['role'],'Night'));Admin::action($admin,'user_save',$edit($idle,$idle['role'],'Day'));Admin::action($admin,'user_toggle',['user_id'=>$idle['id'],'active'=>1]);turn_ok(one($p,'SELECT shift FROM users WHERE id=?',[$idle['id']])['shift']==='Day','Inactive idle account shift edits remain functional without bypassing activation vacancy checks');
 // Completed returns are still outstanding until the authoritative vehicle hold is released.
 $returning=$makeUser('returning');$returnTrip=$makeTrip('GUARD-RETURN',$returning,'Completed');$vehicle=insert($p,'vehicles',['plate_number'=>'GUARD-RETURN','truck_type'=>'Container']);run($p,"INSERT INTO trip_assignments(resource_type,resource_id,trip_id,role) VALUES('vehicle',?,?,'truck')",[$vehicle,$returnTrip]);$blocked(fn()=>Admin::action($admin,'user_toggle',['user_id'=>$returning['id'],'active'=>0]),'Completed pending arrival still blocks account deactivation','GUARD-RETURN');
 $incidentOwner=$makeUser('incident');$incidentTrip=$makeTrip('GUARD-INCIDENT',$incidentOwner,'Completed');$incident=insert($p,'incidents',['incident_ref'=>'GUARD-INCIDENT','trip_id'=>$incidentTrip,'vehicle_id'=>$vehicle,'incident_type'=>'Breakdown','incident_at'=>date('Y-m-d H:i:s'),'location'=>'Fixture yard','problem'=>'Fixture outstanding finding','details'=>'Synthetic guard test','reported_by'=>$incidentOwner['id']]);
 $blocked(fn()=>Admin::action($admin,'user_toggle',['user_id'=>$incidentOwner['id'],'active'=>0]),'Closed trip with unresolved incident still blocks deactivation','GUARD-INCIDENT');run($p,"UPDATE incidents SET status='Resolved' WHERE id=?",[$incident]);Admin::action($admin,'user_toggle',['user_id'=>$incidentOwner['id'],'active'=>0]);turn_ok(true,'Resolved incident and completed history alone allow deactivation');
 turn_denied(fn()=>Admin::action($ops,'user_toggle',['user_id'=>$idle['id'],'active'=>0]),403,'Operations Head gains no account deactivation permission');
 // Controlled ordering with independent database connections, not sequential mock calls.
 $start=function(array $arg,string $expected){$proc=proc_open([PHP_BINARY,__DIR__.'/account_guard_worker.php',json_encode($arg)],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);$line=trim((string)fgets($pipes[1]));if($line!==$expected)throw new RuntimeException('Worker barrier failed');return [$proc,$pipes];};
 $finish=function(array $worker){[$proc,$pipes]=$worker;fclose($pipes[0]);$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);turn_ok($exit===0&&$err==='','Concurrent account worker completes without unhandled error');return json_decode($raw,true,512,JSON_THROW_ON_ERROR);};
 foreach(['outgoing','incoming','role','shift'] as $target){
  $a=$makeUser('race_'.$target.'_out');$b=$makeUser('race_'.$target.'_in','Night');$tid=$makeTrip('GUARD-RACE-'.$target,$a);$pv=Trips::action($a,'turnover_preview',[]);$header=Trips::action($a,'turnover_endorse',['incoming_id'=>$b['id'],'trip_ids'=>array_column($pv['rows'],'id'),'fingerprint'=>$pv['fingerprint'],'request_key'=>turn_key()])['turnover_id'];$who=$target==='outgoing'?$a:$b;
  $change=in_array($target,['role','shift'],true)?['kind'=>'user_save','data'=>$edit($who,$target==='role'?'audit':$who['role'],'Day')]:['kind'=>'user_toggle','data'=>['user_id'=>$who['id'],'active'=>0]];
  $accountWorker=$start(['actor'=>$admin['id'],'hold_account'=>$who['id']]+$change,'READY');
  $acceptWorker=$start(['actor'=>$b['id'],'kind'=>'accept','turnover'=>$header],'STARTED');fwrite($accountWorker[1][0],"go\n");$ar=$finish($accountWorker);$tr=$finish($acceptWorker);
  $owner=(int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$tid])['current_dispatcher_id'];$state=one($p,'SELECT status FROM dispatcher_turnovers WHERE id=?',[$header])['status'];
  turn_ok(!$ar['ok']&&$ar['status']===409&&(!$tr['ok']?$tr['status']===409:true),'Racing '.$target.' account change is blocked or safely conflicts');
  $account=one($p,'SELECT active,role,shift FROM users WHERE id=?',[$who['id']]);
  turn_ok((int)$account['active']===1&&$account['role']===$who['role']&&$account['shift']===$who['shift']&&(($state==='Pending'&&$owner===$a['id'])||($state==='Accepted'&&$owner===$b['id'])),'Race cannot commit inactive/changed participant or invalid responsibility');
  Trips::action($b,'turnover_accept',['turnover_id'=>$header]);turn_ok((int)one($p,'SELECT version FROM trip_responsibilities WHERE trip_id=?',[$tid])['version']===2,'Normal retry settles race with exactly one ownership transfer');
 }
 $a=$makeUser('accept_first_out');$b=$makeUser('accept_first_in','Night');$tid=$makeTrip('GUARD-ACCEPT-FIRST',$a);$pv=Trips::action($a,'turnover_preview',[]);$header=Trips::action($a,'turnover_endorse',['incoming_id'=>$b['id'],'trip_ids'=>array_column($pv['rows'],'id'),'fingerprint'=>$pv['fingerprint'],'request_key'=>turn_key()])['turnover_id'];
 $acceptWorker=$start(['actor'=>$b['id'],'kind'=>'accept','turnover'=>$header,'hold_account'=>$a['id']],'READY');$accountWorker=$start(['actor'=>$admin['id'],'kind'=>'user_toggle','data'=>['user_id'=>$a['id'],'active'=>0]],'STARTED');fwrite($acceptWorker[1][0],"go\n");$tr=$finish($acceptWorker);$ar=$finish($accountWorker);
 turn_ok($tr['ok']&&$ar['ok']&&(int)one($p,'SELECT active FROM users WHERE id=?',[$a['id']])['active']===0&&(int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$tid])['current_dispatcher_id']===$b['id'],'Acceptance winning the lock allows safe outgoing deactivation afterward');
 $a=$makeUser('endorse_race_out');$b=$makeUser('endorse_race_in','Night');$tid=$makeTrip('GUARD-ENDORSE-RACE',$a);$pv=Trips::action($a,'turnover_preview',[]);
 $accountWorker=$start(['actor'=>$admin['id'],'kind'=>'user_toggle','data'=>['user_id'=>$b['id'],'active'=>0],'hold_account'=>$b['id']],'READY');$endorseWorker=$start(['actor'=>$a['id'],'kind'=>'endorse','data'=>['incoming_id'=>$b['id'],'trip_ids'=>array_column($pv['rows'],'id'),'fingerprint'=>$pv['fingerprint'],'request_key'=>turn_key()]],'STARTED');fwrite($accountWorker[1][0],"go\n");$ar=$finish($accountWorker);$er=$finish($endorseWorker);
 turn_ok($ar['ok']&&!$er['ok']&&$er['status']===403,'Idle recipient deactivation winning the lock prevents subsequent endorsement');
 turn_ok((int)one($p,'SELECT COUNT(*) n FROM dispatcher_turnovers WHERE incoming_id=?',[$b['id']])['n']===0&&(int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$tid])['current_dispatcher_id']===$a['id'],'Endorsement race leaves no pending header or silently transferred responsibility');
 // Missing schema must fail closed for Dispatcher changes, not disable unrelated idle account management.
 $p->exec('RENAME TABLE trip_responsibilities TO guard_hidden_responsibilities');try{$blockedMissing=false;try{Admin::action($admin,'user_toggle',['user_id'=>$idle['id'],'active'=>0]);}catch(BusinessRuleException $e){$blockedMissing=$e->httpStatus===409&&str_contains($e->getMessage(),'schema');}turn_ok($blockedMissing,'Missing schema blocks unsafe Dispatcher account changes');}finally{$p->exec('RENAME TABLE guard_hidden_responsibilities TO trip_responsibilities');}
})();
